    getHeader, getMethod: () => req.method, getPath: () => decodedPath,
    getUrl: () => target.href, getAcceptHeader: () => getHeader('accept') ?? '',
    getUserAgent: () => getHeader('user-agent') ?? '', getQueryParams: () => query,
    getQueryParam: name => query[name], getBody: () => body,
